sealed class MtprotoException: kotlin.Exception() {
    
    class UnknownClient(
        ) : MtprotoException() {
        override val message
            get() = ""
    }
    
    class RegistrationRequired(
        ) : MtprotoException() {
        override val message
            get() = ""
    }
    
    class PasswordRequired(
        ) : MtprotoException() {
        override val message
            get() = ""
    }
    
    class Message(
        
        val v1: kotlin.String
        ) : MtprotoException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MtprotoException> {
        override fun lift(error_buf: RustBuffer.ByValue): MtprotoException = FfiConverterTypeMtprotoError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeMtprotoError : FfiConverterRustBuffer<MtprotoException> {
    override fun read(buf: ByteBuffer): MtprotoException {
        

        return when(buf.getInt()) {
            1 -> MtprotoException.UnknownClient()
            2 -> MtprotoException.RegistrationRequired()
            3 -> MtprotoException.PasswordRequired()
            4 -> MtprotoException.Message(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: MtprotoException): ULong {
        return when(value) {
            is MtprotoException.UnknownClient -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is MtprotoException.RegistrationRequired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is MtprotoException.PasswordRequired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is MtprotoException.Message -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: MtprotoException, buf: ByteBuffer) {
        when(value) {
            is MtprotoException.UnknownClient -> {
                buf.putInt(1)
                Unit
            }
            is MtprotoException.RegistrationRequired -> {
                buf.putInt(2)
                Unit
            }
            is MtprotoException.PasswordRequired -> {
                buf.putInt(3)
                Unit
            }
            is MtprotoException.Message -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



